import { ChevronDown, ChevronLeft, ChevronRight, Menu } from "lucide-react";
import {
  useEffect,
  useState,
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
} from "react";
import { Button } from "./Button";
import { mergeClasses } from "./classes";
import { Drawer } from "./Drawer";
import { roundedClasses, type Rounded } from "./form";
import { Icon, type IconComponent } from "./Icon";
import type { Shadow, ThemeInput } from "./theme";
import {
  BalsaThemeContext,
  useControllableState,
  useResolvedThemeProps,
} from "./theme-context";

export interface SidebarItem {
  id: string;
  label: string;
  href?: string;
  icon?: IconComponent;
  badge?: string;
  disabled?: boolean;
  children?: readonly SidebarItem[];
}
export interface SidebarGroup {
  id: string;
  label?: string;
  items: readonly SidebarItem[];
}
export type SidebarVariant = "surface" | "outline" | "soft" | "glass";
export type SidebarSide = "left" | "right";
export type SidebarCollapse = "rail" | "offcanvas" | "none";

export interface SidebarProps extends Omit<HTMLAttributes<HTMLElement>, "onSelect" | "children" | "title" | "id"> {
  id: string;
  label: string;
  groups: readonly SidebarGroup[];
  "data-balsa"?: string;
  "data-palette"?: string;
  side?: SidebarSide;
  variant?: SidebarVariant;
  collapsible?: SidebarCollapse;
  width?: string;
  railWidth?: string;
  mobileBreakpointLabel?: string;
  shortcut?: string;
  rounded?: Rounded;
  shadow?: Shadow;
  theme?: ThemeInput;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  collapsed?: boolean;
  defaultCollapsed?: boolean;
  onCollapsedChange?: (collapsed: boolean) => void;
  mobileOpen?: boolean;
  defaultMobileOpen?: boolean;
  onMobileOpenChange?: (open: boolean) => void;
  onSelect?: (item: SidebarItem) => void;
  header?: (collapsed: boolean) => ReactNode;
  footer?: (collapsed: boolean) => ReactNode;
}

const variantClasses: Readonly<Record<SidebarVariant, string[]>> = {
  surface: ["border-balsa-border", "bg-balsa-surface", "text-balsa-foreground"],
  outline: ["border-balsa-border-strong", "bg-transparent", "text-balsa-foreground"],
  soft: ["border-transparent", "bg-balsa-muted", "text-balsa-foreground"],
  glass: ["border-balsa-border/60", "bg-balsa-surface/60", "text-balsa-foreground", "backdrop-balsa"],
};

export function Sidebar(rawProps: SidebarProps) {
  const { props, theme } = useResolvedThemeProps("sidebar", "navigation", rawProps, {
    variant: "surface",
    rounded: "lg",
    shadow: "auto",
  } as const);
  const {
    id,
    label,
    groups,
    "data-balsa": _dataBalsa,
    "data-palette": dataPalette,
    side = "left",
    variant,
    collapsible = "rail",
    width = "18rem",
    railWidth = "4.5rem",
    mobileBreakpointLabel = "Open navigation",
    shortcut = "b",
    rounded,
    shadow,
    theme: themeInput,
    value,
    defaultValue = "",
    onValueChange,
    collapsed: collapsedProp,
    defaultCollapsed = false,
    onCollapsedChange,
    mobileOpen: mobileOpenProp,
    defaultMobileOpen = false,
    onMobileOpenChange,
    onSelect,
    header,
    footer,
    className,
    style,
    ...domProps
  } = props;
  void _dataBalsa;

  const [active, setActive] = useControllableState({
    value,
    defaultValue,
    onChange: onValueChange,
  });
  const [collapsed, setCollapsed] = useControllableState({
    value: collapsedProp,
    defaultValue: defaultCollapsed,
    onChange: onCollapsedChange,
  });
  const [mobileOpen, setMobileOpen] = useControllableState({
    value: mobileOpenProp,
    defaultValue: defaultMobileOpen,
    onChange: onMobileOpenChange,
  });
  const [expanded, setExpanded] = useState<ReadonlySet<string>>(() => new Set());
  const railCollapsed = collapsed && collapsible === "rail";
  const labelClasses = railCollapsed ? "sr-only" : "min-w-0 flex-1 truncate";

  function itemClasses(item: SidebarItem): string {
    return mergeClasses(
      "flex min-h-9 w-full items-center gap-balsa-sm rounded-balsa-control px-balsa-md py-balsa-2xs text-left text-sm font-semibold no-underline transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-balsa-focus-ring",
      active === item.id
        ? "bg-balsa-selected text-balsa-selected-foreground"
        : "text-balsa-foreground hover:bg-balsa-muted",
      item.disabled && "cursor-not-allowed opacity-45",
      railCollapsed && "justify-center px-balsa-xs",
    );
  }

  function toggleCollapsed(): void {
    if (collapsible !== "none") setCollapsed(!collapsed);
  }

  function select(item: SidebarItem): void {
    if (item.disabled) return;
    if (item.children?.length) {
      setExpanded((current) => {
        const next = new Set(current);
        if (next.has(item.id)) next.delete(item.id);
        else next.add(item.id);
        return next;
      });
      return;
    }
    setActive(item.id);
    setMobileOpen(false);
    onSelect?.(item);
  }

  useEffect(() => {
    function handleShortcut(event: KeyboardEvent): void {
      if (!(event.ctrlKey || event.metaKey) || event.key.toLowerCase() !== shortcut.toLowerCase()) return;
      event.preventDefault();
      if (collapsible !== "none") setCollapsed(!collapsed);
    }
    document.addEventListener("keydown", handleShortcut);
    return () => document.removeEventListener("keydown", handleShortcut);
  }, [shortcut, collapsible, collapsed, setCollapsed]);

  const asideClasses = mergeClasses(
    "hidden h-full shrink-0 flex-col border transition-[width,transform] duration-200 lg:flex",
    variantClasses[variant],
    roundedClasses[rounded],
    collapsible === "offcanvas" && collapsed && "-translate-x-full",
    className,
  );
  const asideStyle = {
    width: railCollapsed ? railWidth : width,
    ...style,
  } as CSSProperties;
  const footerContent = footer?.(collapsed);
  const themeAttrs = {
    "data-theme": theme.explicitPresentation?.id,
    "data-theme-base": theme.explicitPresentation?.base,
    "data-palette": dataPalette,
  };

  function renderItem(item: SidebarItem, options: { rail?: boolean } = {}): ReactNode {
    const content = (
      <>
        {item.icon ? <Icon icon={item.icon} size="md" className="shrink-0" /> : null}
        <span className={options.rail ? labelClasses : "min-w-0 flex-1 truncate"}>{item.label}</span>
        {item.badge && !options.rail ? (
          <span className="text-xs text-balsa-muted-foreground">{item.badge}</span>
        ) : null}
        {item.children?.length && !options.rail ? <Icon icon={ChevronDown} size="md" /> : null}
      </>
    );
    const classNameForItem = itemClasses(item);
    const title = options.rail ? item.label : undefined;
    const control = item.href && !item.children?.length ? (
      <a href={item.href} className={classNameForItem} title={title} onClick={() => select(item)}>
        {content}
      </a>
    ) : (
      <button
        type="button"
        disabled={item.disabled}
        className={classNameForItem}
        title={title}
        onClick={() => select(item)}
      >
        {content}
      </button>
    );
    return (
      <li key={item.id}>
        {control}
        {item.children?.length && expanded.has(item.id) && !options.rail ? (
          <ul className="ml-balsa-xl mt-balsa-3xs space-y-balsa-3xs border-l border-balsa-border pl-balsa-xs">
            {item.children.map((child) => renderItem(child))}
          </ul>
        ) : null}
      </li>
    );
  }

  return (
    <BalsaThemeContext.Provider value={theme}>
      <div
        data-balsa="sidebar-shell"
        {...themeAttrs}
        style={theme.explicitPresentation?.style as CSSProperties | undefined}
        className="contents"
      >
        <aside
          {...domProps}
          id={id}
          data-balsa="sidebar"
          {...themeAttrs}
          data-variant={variant}
          data-shadow={shadow}
          data-side={side}
          data-collapsed={collapsed}
          aria-label={label}
          className={asideClasses}
          style={asideStyle}
        >
          <header className="flex min-h-14 items-center gap-balsa-sm border-b border-balsa-border p-balsa-md">
            {header ? header(collapsed) : <span className={labelClasses}>{label}</span>}
            {collapsible !== "none" ? (
              <Button
                shape="fab"
                size="sm"
                variant="glass"
                prefixIcon={collapsed ? ChevronRight : ChevronLeft}
                aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}
                onClick={toggleCollapsed}
              />
            ) : null}
          </header>
          <nav className="min-h-0 flex-1 overflow-y-auto p-balsa-md" aria-label={label}>
            {groups.map((group) => (
              <section key={group.id} className="mb-balsa-xl last:mb-0">
                {group.label && !railCollapsed ? (
                  <small className="mb-balsa-xs block px-balsa-md text-balsa-muted-foreground">{group.label}</small>
                ) : null}
                <ul className="space-y-balsa-3xs">
                  {group.items.map((item) => renderItem(item, { rail: railCollapsed }))}
                </ul>
              </section>
            ))}
          </nav>
          {footerContent ? (
            <footer className="border-t border-balsa-border p-balsa-md">{footerContent}</footer>
          ) : null}
        </aside>
        <Button
          className="lg:hidden"
          prefixIcon={Menu}
          aria-label={mobileBreakpointLabel}
          onClick={() => setMobileOpen(true)}
        >
          {mobileBreakpointLabel}
        </Button>
        <Drawer
          id={`${id}-mobile`}
          title={label}
          side={side}
          size="lg"
          theme={themeInput}
          open={mobileOpen}
          onOpenChange={setMobileOpen}
          footer={footer ? () => footer(false) : undefined}
        >
          <nav aria-label={label}>
            {groups.map((group) => (
              <section key={group.id} className="mb-balsa-xl">
                {group.label ? (
                  <small className="mb-balsa-xs block text-balsa-muted-foreground">{group.label}</small>
                ) : null}
                {group.items.map((item) => (
                  <button
                    key={item.id}
                    type="button"
                    disabled={item.disabled}
                    className={itemClasses(item)}
                    onClick={() => select(item)}
                  >
                    {item.icon ? <Icon icon={item.icon} size="md" /> : null}
                    <span className="min-w-0 flex-1 text-left">{item.label}</span>
                    {item.badge ? (
                      <span className="text-xs text-balsa-muted-foreground">{item.badge}</span>
                    ) : null}
                  </button>
                ))}
              </section>
            ))}
          </nav>
        </Drawer>
      </div>
    </BalsaThemeContext.Provider>
  );
}

import { extendTailwindMerge, type ClassNameValue } from "tailwind-merge";

/**
 * Every custom scale has to be declared here, not only defined in CSS.
 *
 * tailwind-merge decides which of two classes wins by knowing they belong to
 * the same group. A scale it has not been told about is not a group, so a
 * component's own `gap-balsa-md` and a caller's `gap-3` both survive the merge
 * and whichever CSS rule happens to come last decides — the caller's override
 * silently stops working. That is what happened the moment the spacing scale
 * landed, and it is invisible in the source: the class list looks right.
 */
const twMerge = extendTailwindMerge({
  extend: {
    theme: {
      radius: ["balsa-control", "balsa-surface", "balsa-panel"],
      text: [
        "balsa-2xs",
        "balsa-xs",
        "balsa-sm",
        "balsa-base",
        "balsa-prose",
        "balsa-lg",
        "balsa-xl",
        "balsa-2xl",
        "balsa-3xl",
        "balsa-4xl",
        "balsa-5xl",
        "balsa-6xl",
      ],
      leading: ["balsa-tight", "balsa-snug", "balsa-normal", "balsa-relaxed", "balsa-prose"],
      tracking: ["balsa-title", "balsa-normal", "balsa-label"],
      shadow: [
        "balsa-control",
        "balsa-surface",
        "balsa-panel",
        "balsa-sm",
        "balsa-md",
        "balsa-lg",
        "balsa-detail",
      ],
      spacing: [
        "balsa-4xs",
        "balsa-3xs",
        "balsa-2xs",
        "balsa-xs",
        "balsa-sm",
        "balsa-md",
        "balsa-lg",
        "balsa-xl",
        "balsa-2xl",
        "balsa-3xl",
        "balsa-section-sm",
        "balsa-section-md",
        "balsa-section-lg",
        "balsa-control-inline",
        "balsa-density-compact",
        "balsa-density-default",
        "balsa-density-comfortable",
      ],
    },
    classGroups: {
      // `backdrop-balsa` is a custom utility rather than a value on a scale, so
      // it has to join the group it competes with by name. Without this a
      // caller's `backdrop-blur-none` and the component's `backdrop-balsa` both
      // survive the merge and CSS order decides which blur wins — the same
      // failure the spacing scale hit the moment it landed.
      "backdrop-blur": ["backdrop-balsa", "backdrop-balsa-overlay"],
    },
  },
});

export function mergeClasses(...inputs: unknown[]): string {
  return twMerge(...(inputs as ClassNameValue[]));
}

export function withoutClassAttribute(
  attrs: Readonly<Record<string, unknown>>,
): Record<string, unknown> {
  return Object.fromEntries(
    Object.entries(attrs).filter(([name]) => name !== "class"),
  );
}

import { CircleAlert, CircleCheckBig } from "lucide-react";
import type { IconComponent } from "./Icon";

export const fieldLabelClasses =
  "mb-balsa-2xs block text-sm font-medium leading-snug text-balsa-foreground";

export const fieldHintClasses = "mt-balsa-2xs block text-sm text-balsa-muted-foreground";

export const textControlClasses =
  "w-full rounded-lg border font-balsa-body text-balsa-input-foreground outline-none transition-[border-color,box-shadow,opacity] placeholder:text-balsa-muted-foreground focus:border-balsa-focus-ring focus:ring-2 focus:ring-balsa-focus-ring/30 disabled:border-balsa-border disabled:bg-balsa-disabled disabled:text-balsa-disabled-foreground";

export const textControlPopupClasses =
  "max-h-64 overflow-auto rounded-lg p-balsa-3xs text-balsa-surface-elevated-foreground shadow-balsa-surface transition-[opacity,transform,visibility] duration-balsa-fast ease-balsa";

export const textControlOptionClasses =
  "flex min-h-8 w-full items-center justify-between rounded-md px-balsa-sm py-balsa-2xs text-left text-sm transition-colors";

/*
 * No bare `border`. Tailwind compiles it to a literal 1px, which outranks the
 * `border-width: var(--balsa-border-width)` the stylesheet sets on these
 * controls -- so a checkbox and a radio kept a 1px edge at every border
 * setting while everything around them moved. The colour utilities stay; only
 * the width comes from the token.
 */
export const choiceInputClasses =
  "shrink-0 cursor-pointer appearance-none outline-none transition-[border-color,background-color,box-shadow,opacity] focus-visible:border-balsa-focus-ring focus-visible:ring-2 focus-visible:ring-balsa-focus-ring/30 disabled:cursor-not-allowed disabled:border-balsa-border disabled:bg-balsa-disabled";

export type FieldStatus = "default" | "validated" | "unvalidated";
export type FieldSize = "sm" | "md";
export type FieldVariant = "outline" | "surface" | "soft" | "glass";
export type Rounded = "none" | "sm" | "md" | "lg" | "xl" | "2xl" | "3xl" | "full";
export type TextareaResize = "none" | "vertical" | "both";

export const roundedClasses: Readonly<Record<Rounded, string>> = {
  none: "rounded-none",
  sm: "rounded-sm",
  md: "rounded-md",
  lg: "rounded-lg",
  xl: "rounded-xl",
  "2xl": "rounded-2xl",
  "3xl": "rounded-3xl",
  full: "rounded-full",
};

/**
 * A surface that may be contained by another one.
 *
 * `auto` means "concentric with whatever contains me": the corner follows the
 * containing surface's radius minus the inset between them, so the gap between
 * the two edges stays even instead of thickening at every corner. A surface
 * standing on its own finds nothing published to nest inside and keeps the
 * ordinary surface radius.
 *
 * Kept apart from `Rounded` because that union is shared with text controls,
 * where there is nothing to be concentric with and `auto` would be a value
 * nobody could act on.
 */
export type SurfaceRounded = Rounded | "auto";

export const surfaceRoundedClasses: Readonly<Record<SurfaceRounded, string>> = {
  ...roundedClasses,
  // Deliberately no class. The radius comes from the concentric rule in
  // balsa-theme.css, keyed on data-rounded="auto"; a utility emitted here would
  // outrank it and pin the corner to one value.
  auto: "",
};

const fieldVariantClasses: Readonly<Record<FieldVariant, string>> = {
  outline: "border-balsa-input-border bg-balsa-background",
  surface: "border-balsa-input-border bg-balsa-input",
  soft: "border-transparent bg-balsa-muted",
  glass: "border-balsa-border/70 bg-balsa-surface/70 backdrop-balsa",
};

const fieldPopupVariantClasses: Readonly<Record<FieldVariant, string>> = {
  outline: "border-balsa-input-border bg-balsa-background",
  surface: "border-balsa-border-strong bg-balsa-surface-elevated",
  soft: "border-transparent bg-balsa-muted",
  glass: "border-balsa-border/70 bg-balsa-surface/80 backdrop-balsa",
};

export interface AnchoredPopupPosition {
  left: number;
  top: number;
  width: number;
}

const textControlSizeClasses: Record<FieldSize, string[]> = {
  sm: ["h-8", "px-balsa-md", "text-sm"],
  md: ["h-9", "px-balsa-md", "text-sm"],
};

const textareaResizeClasses: Readonly<Record<TextareaResize, string>> = {
  none: "resize-none",
  vertical: "resize-y",
  both: "resize",
};

export const fieldStatusMessages: Record<
  Extract<FieldStatus, "unvalidated">,
  string
> = {
  unvalidated: "Check this information and try again.",
};

export function getTextControlClasses(
  status: FieldStatus,
  hasAdornment: boolean,
  disabled: boolean,
  loading: boolean,
  size: FieldSize = "md",
  rounded: Rounded = "lg",
  variant: FieldVariant = "surface",
): string[] {
  const resolvedSize = textControlSizeClasses[size] ? size : "md";
  return [
    textControlClasses,
    fieldVariantClasses[variant],
    roundedClasses[rounded],
    ...textControlSizeClasses[resolvedSize],
    ...(loading
      ? ["disabled:cursor-progress"]
      : disabled
        ? ["disabled:cursor-not-allowed"]
        : ["cursor-pointer"]),
    ...(status === "validated" ? ["border-balsa-success", "focus:border-balsa-success"] : []),
    ...(status === "unvalidated"
      ? ["border-balsa-destructive", "focus:border-balsa-destructive", "focus:ring-balsa-destructive/30"]
      : []),
    ...(hasAdornment ? ["pr-10"] : []),
  ];
}

export function getTextControlPopupClasses(
  rounded: Rounded = "lg",
  variant: FieldVariant = "surface",
): string[] {
  return [textControlPopupClasses, roundedClasses[rounded], fieldPopupVariantClasses[variant]];
}

export function getTextareaControlClasses(
  status: FieldStatus,
  disabled: boolean,
  loading: boolean,
  size: FieldSize = "md",
  rounded: Rounded = "lg",
  resizable: TextareaResize = "vertical",
  hasAdornment = false,
  variant: FieldVariant = "surface",
): string[] {
  return [
    textControlClasses,
    fieldVariantClasses[variant],
    "h-auto min-h-0 py-balsa-xs leading-6",
    roundedClasses[rounded],
    textareaResizeClasses[resizable],
    size === "sm" ? "px-balsa-md text-sm leading-5" : "px-balsa-md text-sm leading-6",
    ...(loading
      ? ["disabled:cursor-progress"]
      : disabled
        ? ["disabled:cursor-not-allowed"]
        : ["cursor-text"]),
    ...(status === "validated" ? ["border-balsa-success", "focus:border-balsa-success"] : []),
    ...(status === "unvalidated"
      ? ["border-balsa-destructive", "focus:border-balsa-destructive", "focus:ring-balsa-destructive/30"]
      : []),
    ...(hasAdornment ? ["pr-10"] : []),
  ];
}

export function getChoiceInputClasses(variant: FieldVariant = "surface"): string[] {
  return [choiceInputClasses, fieldVariantClasses[variant]];
}

export function getChoiceTrackClasses(variant: FieldVariant = "surface"): string {
  return fieldVariantClasses[variant];
}

export function getAnchoredPopupPosition(
  trigger: HTMLElement,
  popup: HTMLElement,
  fallbackHeight = 256,
): AnchoredPopupPosition {
  const triggerRect = trigger.getBoundingClientRect();
  const popupRect = popup.getBoundingClientRect();
  const viewportPadding = 8;
  const gap = 8;
  const width = Math.min(
    triggerRect.width,
    window.innerWidth - viewportPadding * 2,
  );
  const height = popupRect.height || fallbackHeight;
  const maxLeft = Math.max(
    viewportPadding,
    window.innerWidth - width - viewportPadding,
  );

  return {
    width,
    left: Math.min(Math.max(triggerRect.left, viewportPadding), maxLeft),
    top:
      triggerRect.bottom + gap + height <= window.innerHeight - viewportPadding
        ? triggerRect.bottom + gap
        : Math.max(viewportPadding, triggerRect.top - height - gap),
  };
}

export function getFieldStatusIcon(status: FieldStatus): IconComponent | undefined {
  if (status === "validated") return CircleCheckBig;
  if (status === "unvalidated") return CircleAlert;
  return undefined;
}

export function getFieldStateColorClass(status: FieldStatus): string {
  if (status === "unvalidated") return "text-balsa-destructive";
  if (status === "validated") return "text-balsa-success";
  return "text-balsa-muted-foreground";
}
